<?php
$complaintQuery = 'SELECT complaints.*, users.full_name AS student_name, students.prn
    FROM complaints JOIN students ON students.id = complaints.student_id
    JOIN users ON users.id = students.user_id';
if ($role === 'student') {
    $statement = $pdo->prepare($complaintQuery . ' WHERE students.user_id = ? ORDER BY complaints.created_at DESC');
    $statement->execute([$user['id']]);
    $complaints = $statement->fetchAll();
} else {
    $complaints = $pdo->query($complaintQuery . ' ORDER BY complaints.updated_at DESC')->fetchAll();
}
?>
<section class="page-heading-row"><div><span class="eyebrow">WE'RE HERE TO HELP</span><h1>Complaints & requests<span class="heading-dot">.</span></h1><p><?= $role === 'student' ? 'Tell us what’s on your mind and follow your request.' : 'Review student requests and keep everyone in the loop.' ?></p></div><span class="count-chip"><?= count($complaints) ?> requests</span></section>
<?php if ($role === 'student'): ?><section class="panel form-panel complaint-form-panel"><div class="panel-heading"><div><span class="eyebrow">A LITTLE HELP GOES A LONG WAY</span><h2>Tell us what’s up</h2></div><span class="complaint-decoration">✳</span></div><form method="post" class="complaint-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_complaint"><input type="hidden" name="return_to" value="complaints"><label class="form-field"><span>Give your request a title</span><input name="title" maxlength="120" required placeholder="e.g. Repair request for my room"></label><label class="form-field"><span>Tell us a little more</span><textarea name="description" rows="4" maxlength="2000" required placeholder="Share the details that will help us look into it…"></textarea></label><div class="form-submit-row"><span>Your request is private and only visible to you and authorized staff.</span><button class="button button-primary" type="submit">Send request <span>→</span></button></div></form></section><?php endif; ?>
<section class="panel table-panel"><div class="panel-heading"><div><span class="eyebrow">KEEPING TRACK</span><h2><?= $role === 'student' ? 'Your requests' : 'All campus requests' ?></h2></div><span class="table-caption"><?= count($complaints) ?> total</span></div>
<?php if ($complaints): ?><div class="table-scroll"><table><thead><tr><?php if ($role !== 'student'): ?><th>STUDENT</th><?php endif; ?><th>REQUEST</th><th>SUBMITTED</th><th>STATUS</th><?php if (in_array($role, ['admin', 'warden'], true)): ?><th>UPDATE STATUS</th><?php endif; ?></tr></thead><tbody><?php foreach ($complaints as $complaint): ?><tr><?php if ($role !== 'student'): ?><td><span class="person-cell"><span class="person-avatar person-color-3"><?= e(strtoupper(substr($complaint['student_name'], 0, 1))) ?></span><span><b><?= e($complaint['student_name']) ?></b><small><?= e($complaint['prn']) ?></small></span></span></td><?php endif; ?><td><div class="complaint-cell"><b><?= e($complaint['title']) ?></b><small><?= e($complaint['description']) ?></small></div></td><td><?= e(date('M j, Y', strtotime($complaint['created_at']))) ?></td><td><span class="status-badge status-<?= e(strtolower(str_replace(' ', '-', $complaint['status']))) ?>"><?= e($complaint['status']) ?></span></td><?php if (in_array($role, ['admin', 'warden'], true)): ?><td><form method="post" class="status-edit-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_complaint"><input type="hidden" name="complaint_id" value="<?= (int) $complaint['id'] ?>"><input type="hidden" name="return_to" value="complaints"><select name="status" aria-label="Update status for <?= e($complaint['title']) ?>"><?php foreach (['Submitted', 'In Progress', 'Resolved', 'Closed'] as $status): ?><option <?= $status === $complaint['status'] ? 'selected' : '' ?>><?= e($status) ?></option><?php endforeach; ?></select><button class="small-action" type="submit">Save</button></form></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-art">✳</span><b>No requests so far</b><p><?= $role === 'student' ? 'Whenever you need support, you can reach out here.' : 'New student requests will appear here.' ?></p></div><?php endif; ?></section>
